const now = new Date();
const toTs = new Date(now.getTime() - 15 * 24 * 60 * 60 * 1000);
const fromTs = new Date(now.getTime() - 45 * 24 * 60 * 60 * 1000);
const toDate = toTs.toISOString().split('T')[0];
const fromDate = fromTs.toISOString().split('T')[0];
return [{ json: { fromDate, toDate } }];

function tsToIso(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'string' && (val.includes('T') || /^\d{4}-/.test(val))) return val;
  const n = parseFloat(val);
  if (isNaN(n)) return null;
  return new Date(n * 1000).toISOString();
}

// Decimal-cohort bug (BACKOFFICE_API_ISSUES.md #2): most orders return charge fields as
// integer cents ("11234"), but a real cohort (confirmed live 2026-08-24: ~20% of recent
// orders, higher than the original ~4% estimate) returns decimal euros ("84.07") with no
// distinguishing flag anywhere in the response. A non-integer value can only be euros --
// cents are always whole numbers -- so that is the test. platform_fee/service_fee
// previously used a naive Math.round(parseFloat(...)) with no cohort handling, silently
// storing "84.07" as 84 cents (EUR 0.84) instead of 8407 cents (EUR 84.07) -- fixed here,
// and reused for the new base_price/services_price/recycling_surcharge columns so they
// don't inherit the same bug.
function parseChargeAmountCents(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = parseFloat(value);
  if (isNaN(n)) return null;
  return Number.isInteger(n) ? Math.round(n) : Math.round(n * 100);
}

function parseManualTotal(charge) {
  if (!charge || charge.charge === null || charge.charge === undefined || charge.charge === '') {
    return { totalInclVatEur: null, totalInclVatCents: null, rawChargeTotal: null };
  }
  const rawChargeTotal = String(charge.charge).trim();
  const cleaned = rawChargeTotal
    .replace(/ /g, '')
    .replace(/€/g, '')
    .replace(/EUR/gi, '')
    .replace(/\s/g, '')
    .replace(',', '.');
  if (!/^[-+]?\d+(\.\d+)?$/.test(cleaned)) {
    return { totalInclVatEur: null, totalInclVatCents: null, rawChargeTotal };
  }
  const totalInclVatEur = parseFloat(cleaned);
  return {
    totalInclVatEur,
    totalInclVatCents: Math.round(totalInclVatEur * 100),
    rawChargeTotal,
  };
}

// Asuntosäätiö B2B deals: 400€ (ALV 0) / 502€ (incl. VAT), always recorded as 0€ by the
// source system since they're free-of-charge to the tenant -- Asuntosäätiö pays Apukuski
// outside the order record. Business rule from Jussi 2026-08-06: flag + override so monthly
// revenue sums aren't silently missing these B2B deals. Manual orders only -- platform orders
// don't have an equivalent single "gig value" field to check against zero.
function isAsuntosaatioMention(d) {
  try {
    return JSON.stringify(d).toLowerCase().includes('asuntosäätiö');
  } catch (e) {
    return false;
  }
}
const ASUNTOSAATIO_EXCL_VAT_EUR = 400;
const ASUNTOSAATIO_INCL_VAT_EUR = 502;

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  const isManual =
    d.isManual === true ||
    d.isManual === 'true' ||
    (d.customer !== undefined && d.additionalInfo !== undefined);

  const manualPricing = isManual ? parseManualTotal(d.charge || null) : null;

  let isAsuntosaatioGig = 'No';
  let manualDataObj = null;

  if (isManual) {
    const isAsuntosaatioOverride =
      isAsuntosaatioMention(d) && manualPricing.totalInclVatEur === 0;
    isAsuntosaatioGig = isAsuntosaatioOverride ? 'Yes' : 'No';

    manualDataObj = {
      customer: d.customer || null,
      additionalInfo: d.additionalInfo || null,
      serviceFeeApplied: d.serviceFeeApplied || null,
      total_incl_vat_eur: isAsuntosaatioOverride ? ASUNTOSAATIO_INCL_VAT_EUR : manualPricing.totalInclVatEur,
      total_incl_vat_cents: isAsuntosaatioOverride ? ASUNTOSAATIO_INCL_VAT_EUR * 100 : manualPricing.totalInclVatCents,
      total_excl_vat_eur: isAsuntosaatioOverride ? ASUNTOSAATIO_EXCL_VAT_EUR : null,
      total_excl_vat_cents: isAsuntosaatioOverride ? ASUNTOSAATIO_EXCL_VAT_EUR * 100 : null,
      price_basis: 'gross_incl_vat',
      raw_charge_total: manualPricing.rawChargeTotal,
      original_total_incl_vat_eur: isAsuntosaatioOverride ? manualPricing.totalInclVatEur : undefined,
      value_override_reason: isAsuntosaatioOverride ? 'asuntosaatio_b2b_flat_rate' : undefined,
    };
  }

  const charge = d.charge || {};
  // total_excl_vat_cents is "valitetty myynti" excl. VAT (the full customer-paid total minus
  // VAT), NOT "liikevaihto" (Apukuski's actual cut, which additionally applies
  // commission_rate to base_price_cents and excludes the partner's share) -- see migration
  // 010 comment and docs/REVENUE_DEFINITIONS.md. servicesPrice/recyclingSurcharge default to
  // 0 when absent (most orders don't have them), matching the validated formula; a missing
  // basePrice or platformFee propagates to a null total rather than a wrong partial sum.
  const basePriceCents = isManual ? null : parseChargeAmountCents(charge.basePrice);
  const servicesPriceCents = isManual ? null : parseChargeAmountCents(charge.servicesPrice);
  const recyclingSurchargeCents = isManual ? null : parseChargeAmountCents(charge.recyclingSurcharge);
  const platformFeeCents = isManual ? null : parseChargeAmountCents(charge.platformFee);
  const serviceFeeCents = isManual ? null : parseChargeAmountCents(charge.serviceFee);
  const totalExclVatCents =
    !isManual && basePriceCents !== null && platformFeeCents !== null
      ? basePriceCents + platformFeeCents + (servicesPriceCents || 0) + (recyclingSurchargeCents || 0)
      : null;

  const transformed = {
    order_id: d.orderId,
    is_manual: isManual,
    created_at: tsToIso(d.created || d.createdAt),
    organization_name: d.organizationName || null,
    org_id: d.orgId || null,
    hub_id: d.hubId || null,
    order_state: d.orderState || null,
    order_type: d.orderType || null,
    origin: isManual ? null : d.origin || null,
    first_schedule: tsToIso(d.firstSchedule),
    schedule: d.schedule || null,
    content: d.content || null,
    stops: d.stops || null,
    charge: d.charge || null,
    platform_fee: platformFeeCents,
    service_fee: serviceFeeCents,
    base_price_cents: basePriceCents,
    services_price_cents: servicesPriceCents,
    recycling_surcharge_cents: recyclingSurchargeCents,
    total_excl_vat_cents: totalExclVatCents,
    route_id: d.routeId || null,
    commission_rate: d.commissionRate !== undefined ? parseFloat(d.commissionRate) : null,
    underway_at: tsToIso(d.underwayAt),
    in_transit_at: tsToIso(d.inTransitAt),
    delivered_at: tsToIso(d.deliveredAt),
    review: d.review || null,
    manual_data: manualDataObj,
    is_asuntosaatio_gig: isAsuntosaatioGig,
    synced_at: new Date().toISOString(),
  };

  if (transformed.order_id) {
    results.push({ json: transformed });
  }
}

return results;
